from __future__ import absolute_import

import logging

from taf.selenium.gnb.oam.coam.cu import pages
from taf.selenium.gnb.oam.coam.cu.pages.panels.view import ViewPanel

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class Diagnostic(pages.Diagnostic):
    """
    The class corresponding to diagnostic page on selenium_coam_vdu web, all operations under diagnostic
    page will be implemented or added in its corresponding classes.
    """

    def __init__(self, driver, version):
        super(Diagnostic, self).__init__(driver, version)
        self._instance_dict.update({"IP Security Associations": IPSecurityAssociations(driver, version)})


class IPSecurityAssociations(object):
    """
    As a class will be called by Diagnostic, all operations Snapshot will be implemented under this class.
    """
    MENU_ROUTE_LIST = ['stethoscope', 'IP Security Associations']

    def __init__(self, driver, version):
        self._view_panel = IPSecurityAssociationsViewPanel(driver, version)

    def get_ip_security_associations(self, pod_information, policy_order_number, timeout):
        """
        This keyword will return the table information of ip_security associations in dict format
        :param pod_information: str, pod information
        :param policy_order_number: int , policy order number
        :param timeout: int, timeout for the element be available to click

        :return: dict, dict of table information of ike_associations and ipsec_associations
        """
        return self._view_panel.get_ip_security_associations(pod_information, policy_order_number, timeout)


class IPSecurityAssociationsViewPanel(ViewPanel):
    def __init__(self, driver, version):
        super(IPSecurityAssociationsViewPanel, self).__init__(driver, version)

    def get_ip_security_associations(self, pod_information, policy_order_number, timeout):
        self.click_enabled_element(self.locator.POD_INFORMATION_DROP_DOWN, timeout)
        self.click_enabled_element(self.locator.CHOOSE_ITEM_FROM_DROP_DOWN.format(pod_information), timeout)
        self.click_enabled_element(self.locator.POLICY_ORDER_NUMBER_DROP_DOWN, timeout)
        self.click_enabled_element(self.locator.CHOOSE_ITEM_FROM_DROP_DOWN.format(policy_order_number), timeout)
        return {"ike_associations": self.get_ike_table_data(),
                "ipsec_associations": self.get_ipsec_table_data()}

    def get_ike_table_data(self):
        if self.element_exists(self.locator.IKE_ASSOCIATIONS_EMPTY_BODY, timeout=3):
            return "No data"
        ike_associations_header = self.get_text_from_all_matching_elements(self.locator.IKE_ASSOCIATIONS_HEADER)
        ike_associations_body = self.get_text_from_all_matching_elements(self.locator.IKE_ASSOCIATIONS_BODY)
        return dict(zip(ike_associations_header, ike_associations_body))

    def get_ipsec_table_data(self):
        if self.element_exists(self.locator.IPSEC_ASSOCIATIONS_EMPTY_BODY, timeout=3):
            return "No data"
        ipsec_associations_header = self.get_text_from_all_matching_elements(self.locator.IPSEC_ASSOCIATIONS_HEADER)
        ipsec_associations_body = self.get_text_from_all_matching_elements(self.locator.IPSEC_ASSOCIATIONS_BODY)
        return dict(zip(ipsec_associations_header, ipsec_associations_body))
